from test_bufftap import test, tests
from test_nearby import setup
# 1.19 scenarios: roles, button side, request to join, helpers layout.
test('Tank role gives a buff regardless of class choice',"BuffTap.db.group=true; local d=BuffTap:FindBuff('thorns'); BuffTap:GroupEditorSettings().buffRoles[BuffTap:RootKey(d)]='tank'; UnitGroupRolesAssigned=function(u) return u=='party2' and 'TANK' or 'NONE' end; BuffTap.roleCache=nil; assert(BuffTap:BuffRoleMode(d)=='tank')")
test('Role mode normalizes unknown values back to class',"local g=BuffTap:GroupEditorSettings(); g.buffRoles={thorns='bogus'}; BuffTap:InitDB(); assert(BuffTap:BuffRoleMode(BuffTap:FindBuff('thorns'))=='class')")
test('Nearby button side setting normalizes and moves the gutter',setup+"BuffTap.db.nearbyButtonSide='middle'; BuffTap:InitDB(); assert(BuffTap.db.nearbyButtonSide=='left'); BuffTap.db.nearbyButtonSide='right'; BuffTap.nearbyFrame.layoutKey=nil; refresh(); assert(BuffTap.db.nearbyButtonSide=='right')")
test('Request to join shows the arrow glyph when the client offers it',setup+"BuffTap.db.nearbyShowAll=true; GetDisplayedInviteType=function() return 'REQUEST_INVITE' end; C_PartyInfo={InviteUnit=function() end,RequestInviteFromUnit=function() end}; UnitInAnyGroup=function(u) return u=='nameplate1' end; refresh(); local r=BuffTap.nearbyFrame.rows[1]; if r.invite.shown then assert(r.invite.arrow.shown and not r.invite.plus.shown) end")
test('Helpers page builds without a scroll frame',"BuffTap:Options(); local h=BuffTap.helperWindow; assert(h and not h.helperScroll and h.requests and h.restoreButton and h.reportButton)")
print('RELEASE 1.19 CHECKS',len(tests))
test('Clear binding needs a second click to confirm',"BuffTap:Options(); local c=BuffTap.options.clearBindingButton; local keys=#BuffTap.db.keys; assert(keys>0); c.scripts.OnClick(c); assert(#BuffTap.db.keys==keys and c.confirmArmed); c.scripts.OnClick(c); assert(#BuffTap.db.keys==0)")
test('An armed confirmation expires on its own',"BuffTap:Options(); local c=BuffTap.options.clearBindingButton; local keys=#BuffTap.db.keys; c.scripts.OnClick(c); advance(5); assert(not c.confirmArmed); c.scripts.OnClick(c); assert(#BuffTap.db.keys==keys)")
# 1.19.2: onboarding, camp sound, full names.
test('Nearby shows the full name by default and first name on request',setup+"BuffTap.db.nearbyShowAll=true; local old=UnitName; UnitName=function(u) local n=old(u); if tostring(u):find('nameplate') then return n,'Stormwind' end return n end; refresh(); local r=BuffTap.nearbyFrame.rows[1]; assert(r.name.text and r.name.text:find(' Stormwind$'),tostring(r.name.text)); BuffTap.db.nearbyFullNames=false; refresh(); assert(not r.name.text:find('Stormwind'))")
test('Old default Nearby width widens once for full names',"BuffTap.db.nearbyWidth=210; BuffTap.db.nearbyNameVersion=nil; BuffTap:NormalizeVisualOptions(); assert(BuffTap.db.nearbyWidth==240); BuffTap.db.nearbyWidth=210; BuffTap:NormalizeVisualOptions(); assert(BuffTap.db.nearbyWidth==210)")
test('Camp reminder plays its own sound',"local heard; PlaySoundFile=function(v) heard=v; return true end; assert(BuffTap.db.campAlertSound=='bell'); assert(BuffTap:PlayAlert('camp',true) and heard:find('BuffTapBell.ogg',1,true))")
test('Leave me alone changes nothing and never asks again',"local before=BuffTap.db.sound; BuffTap.db.onboardingVersion=nil; BuffTap:ShowOnboarding(); assert(BuffTap.onboarding.shown); BuffTap:FinishOnboarding(); assert(not BuffTap:OnboardingPending() and BuffTap.db.sound==before)")
test('Set me up preselects untouched settings and applies only selected ones',"BuffTap.db.onboardingVersion=nil; BuffTap.db.sound=false; BuffTap.db.campSound=false; BuffTap.db.helperThanks=false; BuffTap.db.pauseResting=true; BuffTap:ShowOnboarding(); BuffTap:OnboardingSettingsPage(); local seen={}; for _,c in ipairs(BuffTap.onboarding.choices) do seen[c.spec.key]=c.check:GetChecked() end; assert(seen.sounds==true and seen.thanks==true and seen.resting==nil); for _,c in ipairs(BuffTap.onboarding.choices) do if c.spec.key=='thanks' then c.check:SetChecked(false) end end; BuffTap:ApplyOnboarding(); assert(BuffTap.db.sound==true and BuffTap.db.campSound==true and BuffTap.db.helperThanks==false)")
test('Onboarding never applies during combat',"BuffTap.db.onboardingVersion=nil; BuffTap:ShowOnboarding(); BuffTap:OnboardingSettingsPage(); combat=true; local s=BuffTap.db.sound; BuffTap:ApplyOnboarding(); assert(BuffTap.db.sound==s)")
# Class presets in the one-time setup.
pal="playerClass='PALADIN'; spells={}; book={}; spell(20217,'Blessing of Kings',20); spell(19740,'Blessing of Might',4); spell(19742,'Blessing of Wisdom',4); UnitLevel=function() return 60 end; BuffTap:NormalizeGroupContexts(); refresh(); "
def choices(): return "BuffTap.db.onboardingVersion=nil; BuffTap:ShowOnboarding(); BuffTap:OnboardingSettingsPage(); local pick={}; for _,c in ipairs(BuffTap.onboarding.choices or {}) do pick[c.spec.key]=c end; "
test('Paladin setup builds a class and role blessing plan for party and raid',pal+choices()+"assert(pick.blessings and pick.blessings.check:GetChecked()); BuffTap:ApplyOnboarding(); assert(BuffTap:GroupPreference('blessingAssignments','Party') and BuffTap:GroupPreference('blessingAssignments','Raid')); assert(BuffTap.db.blessingClasses.WARRIOR=='bok' and BuffTap.db.blessingClasses.MAGE=='bok' and BuffTap.db.blessingClasses.DRUID=='bow' and BuffTap.db.blessingClasses.PRIEST=='bow'); assert(BuffTap.db.blessingRaidDefaults.classes.ROGUE=='bok'); assert(BuffTap.db.blessingRoleChoices.Party.TANK.WARRIOR=='bok' and BuffTap.db.blessingRoleChoices.Raid.HEALER.PRIEST=='bow')")
test('Paladin setup is not offered once blessings were planned',pal+"BuffTap.db.blessingClasses={WARRIOR='bow'}; "+choices()+"assert(not pick.blessings)")
test('Classes already at the baseline say so',"playerClass='WARRIOR'; refresh(); "+choices()+"assert(not pick.blessings and not pick.thorns)")
test('Druid setup puts Thorns on tanks in party and raid',"spell(467,'Thorns',6); refresh(); "+choices()+"assert(pick.thorns); BuffTap:ApplyOnboarding(); local root=BuffTap:RootKey(BuffTap:FindBuff('thorns')); assert(BuffTap:GroupSettings('Party').buffRoles[root]=='tank' and BuffTap:GroupSettings('Raid').buffRoles[root]=='tank')")
test('Priest Fear Ward preset appears only when the spell is known',"playerClass='PRIEST'; spells={}; book={}; BuffTap:NormalizeGroupContexts(); refresh(); "+choices()+"assert(not pick['fear-ward']); spell(6346,'Fear Ward',20); refresh(); BuffTap:OnboardingSettingsPage(); local p2={}; for _,c in ipairs(BuffTap.onboarding.choices) do p2[c.spec.key]=c end; assert(p2['fear-ward'] and not p2['fear-ward'].check:GetChecked()); p2['fear-ward'].check:SetChecked(true); BuffTap:ApplyOnboarding(); assert(BuffTap.db.buffs['fear-ward']==true)")
test('Hiding the setup (cinematic, loading screen) does not count as Leave me alone',"BuffTap.db.onboardingVersion=nil; BuffTap:ShowOnboarding(); BuffTap.onboarding:Hide(); assert(BuffTap:OnboardingPending())")
test('Setup waits while the UI is hidden and then appears',"BuffTap.db.onboardingVersion=nil; UIParent.IsVisible=function() return false end; BuffTap:ShowOnboarding(); assert(not (BuffTap.onboarding and BuffTap.onboarding.shown)); UIParent.IsVisible=function() return true end; advance(3.1); assert(BuffTap.onboarding.shown)")
test('Finishing the setup replaces the old first-use card',"BuffTap.db.onboardingVersion=nil; BuffTap.db.welcomeSeen=false; BuffTap:ShowOnboarding(); BuffTap:FinishOnboarding(); advance(5); assert(BuffTap.db.welcomeSeen and not (BuffTap.welcome and BuffTap.welcome.shown))")
test('Buff requests default to what helps the player class',"playerClass='WARLOCK'; local might=BuffTap:FindBuff('bom'); local ai=BuffTap:FindBuff('ai'); local kings=BuffTap:FindBuff('bok'); assert(not BuffTap:RequestEnabled(might) and BuffTap:RequestEnabled(ai) and BuffTap:RequestEnabled(kings)); playerClass='WARRIOR'; assert(BuffTap:RequestEnabled(might) and not BuffTap:RequestEnabled(ai)); BuffTap.db.requestBuffs.ai=true; assert(BuffTap:RequestEnabled(ai))")
test('Warlock setup offers class readiness',"playerClass='WARLOCK'; BuffTap.readinessClassToken=nil; BuffTap:NormalizeGroupContexts(); refresh(); "+choices()+"assert(pick.helperPet and pick.helperHealthstone and pick.helperSoulstone); BuffTap:ApplyOnboarding(); assert(BuffTap.db.helperPet and BuffTap.db.helperSoulstone)")
test('Shadow Protection is not requested by default',"local sp=BuffTap:FindBuff('sp'); assert(not BuffTap:RequestEnabled(sp)); BuffTap.db.requestBuffs.sp=true; assert(BuffTap:RequestEnabled(sp))")
# Buffing-expert defaults (no setup needed).
test('Situational buffs are not offered to friendly targets by default',"for _,k in ipairs({'dampen','amplify','sp','fear-ward','water-breathing','unending-breath','detect-invis'}) do assert(not BuffTap:TargetBuffEnabled(BuffTap:FindBuff(k)),k) end; assert(BuffTap:TargetBuffEnabled(BuffTap:FindBuff('motw')) and BuffTap:TargetBuffEnabled(BuffTap:FindBuff('fort')))")
test('Intellect and Spirit go to mana users by default',"local ai=BuffTap:FindBuff('ai'); assert(not BuffTap:GroupClassAllowed(ai,'WARRIOR') and not BuffTap:GroupClassAllowed(ai,'ROGUE') and BuffTap:GroupClassAllowed(ai,'HUNTER') and BuffTap:GroupClassAllowed(BuffTap:FindBuff('spirit'),'PRIEST'))")
test('Low-level fallbacks are on by default: Rockbiter and Aspect of the Monkey',"assert(BuffTap:Enabled(BuffTap:FindBuff('rockbiter')) and BuffTap:Enabled(BuffTap:FindBuff('aspect-monkey')))")
test('Paladin without Kings defaults to Might, with Kings to Kings only',"playerClass='PALADIN'; spells={}; book={}; spell(19740,'Blessing of Might',4); refresh(); assert(BuffTap:Enabled(BuffTap:FindBuff('bom'))); spell(20217,'Blessing of Kings',20); BuffTap.resolveCache=nil; refresh(); assert(not BuffTap:Enabled(BuffTap:FindBuff('bom')) and BuffTap:Enabled(BuffTap:FindBuff('bok')))")
test('Turning Nearby on the first time shows the introduction instead',"BuffTap.db.nearbyEnabled=false; BuffTap.db.nearbyIntroSeen=nil; BuffTap:ToggleNearby(); assert(not BuffTap.db.nearbyEnabled and BuffTap.nearbyIntro.shown)")
test('The introduction applies invites, requests and all players, then turns Nearby on',"BuffTap.db.nearbyEnabled=false; BuffTap.db.nearbyIntroSeen=nil; BuffTap.db.nearbyRequests=false; BuffTap:ToggleNearby(); BuffTap:ApplyNearbyIntro(); assert(BuffTap.db.nearbyEnabled and BuffTap.db.nearbyInvites and BuffTap.db.nearbyRequests and BuffTap.db.nearbyShowAll and BuffTap.db.nearbyIntroSeen and not BuffTap.nearbyIntro.shown)")
test('Not now leaves Nearby off and does not ask again',"BuffTap.db.nearbyEnabled=false; BuffTap.db.nearbyIntroSeen=nil; BuffTap:ToggleNearby(); BuffTap.nearbyIntro.later.scripts.OnClick(); assert(not BuffTap.db.nearbyEnabled and BuffTap.db.nearbyIntroSeen); BuffTap:ToggleNearby(); assert(BuffTap.db.nearbyEnabled)")
test('Existing Nearby users never see the introduction',"BuffTap.db.nearbyEnabled=true; BuffTap.db.nearbyIntroSeen=nil; BuffTap:InitDB(); assert(BuffTap.db.nearbyIntroSeen)")
test('Shaman spec rows behave like one choice and apply the imbue',"playerClass='SHAMAN'; refresh(); "+choices()+"assert(pick.shamanCaster and pick.shamanHealer and not pick.shamanCaster.check:GetChecked()); pick.shamanHealer.check:SetChecked(true); BuffTap:ApplyOnboarding(); assert(BuffTap.db.buffs.flametongue==true and BuffTap.db.buffs.windfury==false and BuffTap.db.buffs['water-shield']==true)")
test('Modern icon is an optional setup choice',choices()+"assert(pick.modern and not pick.modern.check:GetChecked()); pick.modern.check:SetChecked(true); BuffTap:ApplyOnboarding(); assert(BuffTap.db.iconStyle=='modern')")
test('Copy page lists other characters and copies one',"BuffTap.db.onboardingVersion=nil; BuffTap:ShowOnboarding(); local names=BuffTap:ProfileNames(); BuffTap:OnboardingCopyPage(); assert(BuffTap.onboarding.shown)")
test('Last page offers binding and customization shortcuts',"BuffTap.db.onboardingVersion=nil; BuffTap:ShowOnboarding(); BuffTap:OnboardingFeaturesPage(); local found=0; for _,r in ipairs(BuffTap.onboarding.pageRegions) do if r.text=='Change binding' or r.text=='Customize reminders' then found=found+1 end end; assert(found==2)")
test('Edit Mode moves Nearby and camp placeholders and saves their positions',"BuffTap.db.nearbyEnabled=true; BuffTap.db.campReminder=true; BuffTap:SetEditModeActive(true); local n,c=BuffTap.editNearby,BuffTap.editCamp; assert(n,'n'); assert(c,'c'); assert(n.shown,'ns'); assert(c.shown,'cs'); n.GetCenter=function() return 700,500 end; n.scripts.OnDragStop(n); c.GetCenter=function() return 400,300 end; c.scripts.OnDragStart(c); BuffTap:SetEditModeActive(false); assert(BuffTap.db.nearbyX==200 and BuffTap.db.nearbyY==0,'nxy '..tostring(BuffTap.db.nearbyX)); assert(BuffTap.db.campX==-100 and BuffTap.db.campY==-200,'cxy '..tostring(BuffTap.db.campX)); assert(not n.shown and not c.shown,'hidden')")
test('Edit Mode skips movers for features that are off',"BuffTap.db.nearbyEnabled=false; BuffTap.db.campReminder=false; BuffTap:SetEditModeActive(true); assert(not BuffTap.editNearby and not BuffTap.editCamp); BuffTap:SetEditModeActive(false)")
test('Nearby pitch fits the class and the setup previews before enabling',"assert(BuffTap:NearbyPitch('WARRIOR'):find('Mage, Priest') and BuffTap:NearbyPitch('MAGE'):find('missing your buff')); BuffTap.db.nearbyEnabled=false; BuffTap.db.onboardingVersion=nil; BuffTap:ShowOnboarding(); BuffTap:OnboardingFeaturesPage(); local b; for _,r in ipairs(BuffTap.onboarding.pageRegions) do if r.text=='See how Nearby works' then b=r end end; assert(b,'button'); b.scripts.OnClick(b); assert(BuffTap.nearbyIntro.shown,'shown'); assert(not BuffTap.db.nearbyEnabled,'off'); assert(BuffTap.nearbyIntro.pitch.text,'pt '..tostring(playerClass))")
test('Nearby list text follows the font settings and rows grow to fit',setup+"refresh(); local r=BuffTap.nearbyFrame.rows[1]; assert(BuffTap:NearbyRowHeight()==21); BuffTap.db.nearbyFontSize=18; BuffTap.db.nearbyFontOutline='outline'; BuffTap:NormalizeVisualOptions(); refresh(); local path,size,flags=BuffTap:NearbyFont(); assert(size==18 and flags=='OUTLINE' and BuffTap:NearbyRowHeight()==28); BuffTap.db.nearbyFontSize=99; BuffTap.db.nearbyFontOutline='bogus'; BuffTap:NormalizeVisualOptions(); assert(BuffTap.db.nearbyFontSize==20 and BuffTap.db.nearbyFontOutline=='none')")
test('Forever is recognised by game type, interface number or version',"WOW_PROJECT_ID=18; assert(BuffTap:IsForever()); WOW_PROJECT_ID=1; local g=GetBuildInfo; GetBuildInfo=function() return '1.61.0','1','',16100 end; assert(BuffTap:IsForever()); GetBuildInfo=function() return '12.1.5','1','',120105 end; assert(not BuffTap:IsForever()); GetBuildInfo=g; WOW_PROJECT_ID=nil")
